declare v_customer_suspended boolean; v_caterer_suspended boolean;
begin
 if tg_op='UPDATE' and new.status is not distinct from old.status then return new; end if;
 if tg_op='UPDATE' and new.status not in ('pending','confirmed','awaiting_payment','paid','ongoing') then return new; end if;
 select (p.status='suspended' or coalesce(m.suspended,false)) into v_customer_suspended
 from public.profiles p left join public.account_monitoring_cases m on m.user_id=p.id
 where p.id=new.customer_id;
 select (p.status='suspended' or c.account_standing='suspended' or coalesce(m.suspended,false))
 into v_caterer_suspended
 from public.caterers c join public.profiles p on p.id=c.user_id
 left join public.account_monitoring_cases m on m.user_id=p.id
 where c.id=new.caterer_id;
 if coalesce(v_customer_suspended,false) or coalesce(v_caterer_suspended,false) then
   raise exception 'Booking action unavailable: account suspended' using errcode='42501';
 end if;
 return new;
end

