        a.action = 'maintenance_enabled'
        AND a.details->>'previous_enabled' = 'false'
        AND a.details->>'new_enabled' = 'true'
      )
    )
    AND a.created_at > COALESCE((
      SELECT max(d.created_at)
      FROM public.system_audit_logs AS d
      WHERE d.action IN (
        'maintenance_disabled',
        'maintenance_deadline_session_completed'
      )
    ), '-infinity'::timestamptz)
    ORDER BY a.created_at DESC
    LIMIT 1;

    IF v_started_at IS NULL THEN
      RAISE EXCEPTION
        'No reliable start audit was found for the current maintenance session';
    END IF;

    IF v_started_at > v_ended_at THEN
      RAISE EXCEPTION 'Maintenance session start is in the future';
    END IF;

    -- Ordinary users cannot authorize this update: it also requires the
    -- database function owner's execution role inside the trigger.
    PERFORM pg_catalog.set_config(
      'caterconnect.maintenance_deadline_adjustment', 'on', true
    );

    UPDATE public.bookings AS b
    SET refund_due_at = b.refund_due_at
      + (v_ended_at - GREATEST(v_started_at, b.cancelled_at))
    WHERE b.status = 'cancelled'
      AND b.refund_status = 'pending'
      AND b.refund_amount > 0
      AND b.refund_due_at IS NOT NULL
      AND b.cancelled_at IS NOT NULL
      AND b.refund_due_at > v_started_at
      AND b.cancelled_at < v_ended_at
      AND b.refund_due_at > b.cancelled_at;

    GET DIAGNOSTICS v_refund_count = ROW_COUNT;

    UPDATE public.bookings AS b
    SET downpayment_deadline = b.downpayment_deadline
      + (v_ended_at - GREATEST(v_started_at, b.created_at))
    WHERE b.status = 'confirmed'
      AND b.downpayment_deadline IS NOT NULL
      AND b.created_at IS NOT NULL
      AND b.downpayment_deadline > v_started_at
      AND b.created_at < v_ended_at
      AND b.downpayment_deadline > b.created_at;

    GET DIAGNOSTICS v_downpayment_count = ROW_COUNT;

    PERFORM pg_catalog.set_config(
      'caterconnect.maintenance_deadline_adjustment', 'off', true
    );

    INSERT INTO public.system_audit_logs(
      actor_id, action, details, created_at
    )
    VALUES (
      v_actor,
      'maintenance_deadline_session_completed',
      jsonb_build_object(
        'start_audit_id', v_session_log_id,
        'started_at', v_started_at,
        'ended_at', v_ended_at,
        'duration_seconds', extract(epoch from (v_ended_at - v_started_at)),
        'refund_deadlines_extended', v_refund_count,
        'downpayment_deadlines_extended', v_downpayment_count
      ),
      v_ended_at
    );
  END IF;

  UPDATE public.system_settings
  SET maintenance_enabled = p_enabled,
      maintenance_message = trim(p_message),
      estimated_end_at = CASE
        WHEN p_enabled THEN p_estimated_end_at
        ELSE NULL
      END,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  WHERE id = 'main';

  INSERT INTO public.system_audit_logs(actor_id, action, details)
  VALUES (
    v_actor,
    CASE WHEN p_enabled
      THEN 'maintenance_enabled'
      ELSE 'maintenance_disabled'
    END,
    jsonb_build_object(
      'previous_enabled', v_previous,
      'new_enabled', p_enabled,
      'message', trim(p_message),
      'reason', trim(p_reason),
      'estimated_end_at',
      CASE WHEN p_enabled THEN p_estimated_end_at ELSE NULL END
    )
  );
END;
$function$

