DECLARE
  v_authorized_adjustment boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_authorized_adjustment :=
      current_setting('caterconnect.maintenance_deadline_adjustment', true) = 'on'
      AND current_user = (
        SELECT pg_get_userbyid(p.proowner)
        FROM pg_catalog.pg_proc p
        WHERE p.oid = 'public.set_maintenance_mode(boolean,text,text,timestamp with time zone)'::regprocedure
      );
  END IF;

  IF NEW.status = 'cancelled'
     AND NEW.refund_status = 'pending'
     AND COALESCE(NEW.refund_amount, 0) > 0 THEN
    IF TG_OP = 'INSERT' OR OLD.refund_due_at IS NULL THEN
      NEW.refund_due_at := COALESCE(NEW.cancelled_at, now()) + interval '72 hours';
    ELSIF NOT v_authorized_adjustment THEN
      NEW.refund_due_at := OLD.refund_due_at;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND NOT v_authorized_adjustment THEN
    NEW.refund_due_at := OLD.refund_due_at;
  END IF;

  RETURN NEW;
END;

